def getTime(**_extra):
    import json, os, datetime, time, uuid, re, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0004000" if __import__("os").path.isdir("./environment_mix/0004000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        s = dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return s

    def _floor_minute(dt):
        return dt.replace(second=0, microsecond=0)

    def _floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_ulid_like(prefix):
        # Not a true ULID; vendor datastore contains ids like ts_req_01..., but uniqueness is what matters here.
        return f"{prefix}_{uuid.uuid4().hex}"

    api_keys = _load("api_keys.json")
    counters = _load("rate_limit_counters.json")
    events = _load("request_events.json")

    # Ensure collection shapes are lists
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(counters, list):
        counters = []
    if not isinstance(events, list):
        events = []

    occurred_at = _iso_z(now)
    ts = float(now.timestamp())

    # Ambient auth resolution:
    # If the system has active keys, backend requires auth and picks a working active key context.
    # If there are no keys at all, allow anonymous (api_key_id = None).
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if len(api_keys) > 0 and not active_keys:
        # No working combination in store can serve authenticated calls.
        latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
        ev = {
            "id": _new_ulid_like("ts_req"),
            "api_key_id": None,
            "tool_name": "getTime",
            "request_payload": {},
            "timestamp_input": None,
            "response_payload": None,
            "http_status": 401,
            "error_code": "UNAUTHORIZED",
            "error_message": "authentication required but no active API key is available",
            "latency_ms": latency_ms,
            "client_ip": None,
            "user_agent": None,
            "occurred_at": occurred_at,
            "created_at": occurred_at,
            "updated_at": occurred_at,
        }
        events.append(ev)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "Authentication required but no active API key is available")

    api_key = active_keys[0] if active_keys else None
    api_key_id = api_key.get("id") if api_key else None

    def _upsert_counter(api_key_id, window_type, window_start_iso):
        # Enforce referential integrity: api_key_id must exist when non-null.
        if api_key_id is None:
            return None
        # Find existing
        for row in counters:
            if not isinstance(row, dict):
                continue
            if row.get("api_key_id") == api_key_id and row.get("window_type") == window_type and row.get("window_start") == window_start_iso:
                c = row.get("count")
                if not isinstance(c, int) or c < 0:
                    c = 0
                row["count"] = c + 1
                row["updated_at"] = occurred_at
                return row
        # Create new
        row = {
            "id": _new_ulid_like("ts_rlc"),
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": window_start_iso,
            "count": 1,
            "created_at": occurred_at,
            "updated_at": occurred_at,
        }
        counters.append(row)
        return row

    def _get_counter_count(api_key_id, window_type, window_start_iso):
        for row in counters:
            if not isinstance(row, dict):
                continue
            if row.get("api_key_id") == api_key_id and row.get("window_type") == window_type and row.get("window_start") == window_start_iso:
                c = row.get("count")
                return c if isinstance(c, int) and c >= 0 else 0
        return 0

    http_status = 200
    error_code = None
    error_message = None
    response_payload = None

    # Enforce rate limits when operating under an API key context
    if api_key is not None:
        rpm = api_key.get("rate_limit_rpm")
        dlim = api_key.get("daily_limit")
        if not isinstance(rpm, int) or rpm < 0:
            # Store is inconsistent; treat as internal error rather than silently allow.
            http_status = 500
            error_code = "INTERNAL_ERROR"
            error_message = "invalid rate_limit_rpm configuration"
        elif not isinstance(dlim, int) or dlim < 0:
            http_status = 500
            error_code = "INTERNAL_ERROR"
            error_message = "invalid daily_limit configuration"
        else:
            min_start = _iso_z(_floor_minute(now))
            day_start = _iso_z(_floor_day(now))

            # Check current counts BEFORE increment
            minute_count = _get_counter_count(api_key_id, "minute", min_start)
            day_count = _get_counter_count(api_key_id, "day", day_start)

            if rpm == 0:
                http_status = 429
                error_code = "RATE_LIMIT_MINUTE_EXCEEDED"
                error_message = "rate limit exceeded (minute)"
            elif minute_count >= rpm:
                http_status = 429
                error_code = "RATE_LIMIT_MINUTE_EXCEEDED"
                error_message = "rate limit exceeded (minute)"
            elif dlim == 0:
                http_status = 429
                error_code = "DAILY_QUOTA_EXCEEDED"
                error_message = "daily request quota exceeded"
            elif day_count >= dlim:
                http_status = 429
                error_code = "DAILY_QUOTA_EXCEEDED"
                error_message = "daily request quota exceeded"

            # Upsert + increment atomically for success OR limit-rejected requests
            if http_status in (200, 429):
                _upsert_counter(api_key_id, "minute", min_start)
                _upsert_counter(api_key_id, "day", day_start)

                # Update api_keys.last_used_at for observable dynamics
                api_key["last_used_at"] = occurred_at
                api_key["updated_at"] = occurred_at

    if http_status == 200:
        response_payload = {"timestamp": ts}

    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))

    # Record request event for EVERY call
    ev = {
        "id": _new_ulid_like("ts_req"),
        "api_key_id": api_key_id,
        "tool_name": "getTime",
        "request_payload": {},
        "timestamp_input": None,
        "response_payload": response_payload if http_status == 200 else None,
        "http_status": http_status,
        "error_code": error_code,
        "error_message": (error_message[:200] if isinstance(error_message, str) else None),
        "latency_ms": latency_ms,
        "client_ip": None,
        "user_agent": None,
        "occurred_at": occurred_at,
        "created_at": occurred_at,
        "updated_at": occurred_at,
    }
    events.append(ev)

    # Persist side effects
    _save("request_events.json", events)
    _save("rate_limit_counters.json", counters)
    _save("api_keys.json", api_keys)

    if http_status == 200:
        return {
            "timestamp": ts,
            "meta": {
                "api_key_id": api_key_id,
                "request_event_id": ev["id"],
                "occurred_at": occurred_at,
            },
        }
    if http_status == 429:
        return _err("RATE_LIMIT", error_message or "rate limit exceeded", api_key_id=api_key_id)
    if http_status == 401:
        return _err("UNAUTHORIZED", error_message or "unauthorized", api_key_id=api_key_id)
    if http_status == 403:
        return _err("UNAUTHORIZED", error_message or "forbidden", api_key_id=api_key_id)
    if http_status == 400:
        return _err("VALIDATION_ERROR", error_message or "bad request", api_key_id=api_key_id)
    return _err("CONFLICT" if error_code == "CONFLICT" else "VALIDATION_ERROR" if http_status == 400 else "CONFLICT" if http_status == 409 else "UNAUTHORIZED" if http_status in (401, 403) else "RATE_LIMIT" if http_status == 429 else "CONFLICT" if http_status == 409 else "CONFLICT" if http_status == 412 else "CONFLICT" if http_status == 422 else "CONFLICT" if http_status == 423 else "CONFLICT" if http_status == 424 else "CONFLICT" if http_status == 428 else "CONFLICT" if http_status == 451 else "CONFLICT" if http_status == 499 else "CONFLICT" if http_status == 500 else "CONFLICT", error_message or "request failed", api_key_id=api_key_id)

def readableTime(timestamp, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0004000" if __import__("os").path.isdir("./environment_mix/0004000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)
    occurred_at = now.isoformat()

    api_keys = _load("api_keys.json")
    counters = _load("rate_limit_counters.json")
    events = _load("request_events.json")
    conversions = _load("time_conversions.json")

    # Ambient authentication: choose a working active key if any exist; otherwise operate anonymously.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    api_key = active_keys[0] if active_keys else None
    api_key_id = api_key.get("id") if api_key else None

    def _dt_floor_minute(dt):
        return dt.replace(second=0, microsecond=0)

    def _dt_floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _iso(dt):
        return dt.isoformat()

    def _upsert_and_inc(api_key_id, window_type, window_start_iso):
        nonlocal counters
        for row in counters:
            if row.get("api_key_id") == api_key_id and row.get("window_type") == window_type and row.get("window_start") == window_start_iso:
                c = row.get("count")
                if not isinstance(c, int) or c < 0:
                    row["count"] = 0
                row["count"] += 1
                row["updated_at"] = occurred_at
                return row
        row = {
            "id": "rlc_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": window_start_iso,
            "count": 1,
            "created_at": occurred_at,
            "updated_at": occurred_at,
        }
        counters.append(row)
        return row

    http_status = 200
    error_code = None
    error_message = None
    response_payload = None

    # Validate timestamp
    if timestamp is None or not isinstance(timestamp, (int, float)) or (isinstance(timestamp, float) and (math.isnan(timestamp) or math.isinf(timestamp))):
        http_status = 400
        error_code = "VALIDATION_ERROR"
        error_message = "timestamp is required and must be a finite number."
    else:
        # Range per schema
        if timestamp < -62135596800 or timestamp > 253402300799:
            http_status = 400
            error_code = "OUT_OF_RANGE"
            error_message = "timestamp is outside the supported range."

    format_pattern = "RFC3339_UTC_v1"
    timezone_name = "UTC"

    try:
        # Rate limiting (only when an api_key is used). Validation errors still recorded; only successful or rejected due to limits increment.
        if api_key is not None:
            rpm = api_key.get("rate_limit_rpm")
            dlim = api_key.get("daily_limit")
            if not isinstance(rpm, int) or rpm < 0 or not isinstance(dlim, int) or dlim < 0:
                http_status = 500
                error_code = "CONFLICT"
                error_message = "Server configuration error for key limits."
            else:
                minute_start = _iso(_dt_floor_minute(now))
                day_start = _iso(_dt_floor_day(now))

                minute_count = 0
                day_count = 0
                for row in counters:
                    if row.get("api_key_id") == api_key_id and row.get("window_type") == "minute" and row.get("window_start") == minute_start:
                        if isinstance(row.get("count"), int) and row["count"] >= 0:
                            minute_count = row["count"]
                    if row.get("api_key_id") == api_key_id and row.get("window_type") == "day" and row.get("window_start") == day_start:
                        if isinstance(row.get("count"), int) and row["count"] >= 0:
                            day_count = row["count"]

                if rpm > 0 and minute_count >= rpm:
                    http_status = 429
                    error_code = "RATE_LIMIT"
                    error_message = "Rate limit exceeded (per-minute)."
                    _upsert_and_inc(api_key_id, "minute", minute_start)
                    _upsert_and_inc(api_key_id, "day", day_start)
                elif dlim > 0 and day_count >= dlim:
                    http_status = 429
                    error_code = "QUOTA_EXCEEDED"
                    error_message = "Daily request limit exceeded."
                    _upsert_and_inc(api_key_id, "minute", minute_start)
                    _upsert_and_inc(api_key_id, "day", day_start)
                else:
                    # Only increment on success or limit-rejected; do not increment for validation errors.
                    if http_status == 200:
                        _upsert_and_inc(api_key_id, "minute", minute_start)
                        _upsert_and_inc(api_key_id, "day", day_start)

        if http_status == 200:
            # Cache lookup: only valid rows may be used
            cached = None
            for row in conversions:
                if (
                    row.get("timestamp") == timestamp
                    and row.get("format_pattern") == format_pattern
                    and row.get("timezone") == timezone_name
                    and row.get("status") == "valid"
                ):
                    cached = row
                    break

            if cached is not None and isinstance(cached.get("readable_text"), str):
                readable = cached["readable_text"]
                cached["updated_at"] = occurred_at
            else:
                # Compute formatting
                dt = datetime.datetime.fromtimestamp(float(timestamp), tz=datetime.timezone.utc)
                readable = dt.isoformat().replace("+00:00", "Z")
                # Upsert conversion row (unique(timestamp, format_pattern, timezone))
                existing = None
                for row in conversions:
                    if row.get("timestamp") == timestamp and row.get("format_pattern") == format_pattern and row.get("timezone") == timezone_name:
                        existing = row
                        break
                if existing is None:
                    conversions.append({
                        "id": "tc_" + uuid.uuid4().hex,
                        "timestamp": timestamp,
                        "format_pattern": format_pattern,
                        "timezone": timezone_name,
                        "readable_text": readable,
                        "status": "valid",
                        "created_at": occurred_at,
                        "updated_at": occurred_at,
                    })
                else:
                    # If existing is invalidated, keep it invalidated (do not serve), but refresh content if it matches pattern/timezone.
                    if existing.get("status") == "valid":
                        existing["readable_text"] = readable
                        existing["updated_at"] = occurred_at
                    else:
                        # create a new row is not allowed by unique constraint; instead, do not flip status back.
                        existing["readable_text"] = readable
                        existing["updated_at"] = occurred_at

            response_payload = {"readable": readable, "format_pattern": format_pattern, "timezone": timezone_name}

            if api_key is not None:
                api_key["last_used_at"] = occurred_at
                api_key["updated_at"] = occurred_at
    except Exception as e:
        http_status = 500
        error_code = "CONFLICT"
        error_message = str(e)[:200]

    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))

    event = {
        "id": "re_" + uuid.uuid4().hex,
        "api_key_id": api_key_id,
        "tool_name": "readableTime",
        "request_payload": {"timestamp": timestamp},
        "timestamp_input": timestamp,
        "response_payload": response_payload if http_status == 200 else None,
        "http_status": int(http_status),
        "error_code": error_code,
        "error_message": error_message,
        "latency_ms": int(latency_ms),
        "client_ip": None,
        "user_agent": None,
        "occurred_at": occurred_at,
        "created_at": occurred_at,
        "updated_at": occurred_at,
    }
    events.append(event)

    _save("request_events.json", events)
    _save("rate_limit_counters.json", counters)
    _save("time_conversions.json", conversions)
    _save("api_keys.json", api_keys)

    if http_status == 200:
        return {"readable": response_payload["readable"], "format_pattern": format_pattern, "timezone": timezone_name}
    if http_status == 429:
        return _err(error_code, error_message, http_status=http_status)
    if http_status in (401, 403):
        return _err("UNAUTHORIZED", error_message or "Unauthorized.", http_status=http_status)
    if http_status == 400:
        # Preserve OUT_OF_RANGE vs VALIDATION_ERROR
        return _err(error_code or "VALIDATION_ERROR", error_message or "Bad request.", http_status=http_status)
    return _err(error_code or "CONFLICT", error_message or "Request failed.", http_status=http_status)

def updateApiKey(id, name=None, rate_limit_rpm=None, daily_limit=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0004000" if __import__("os").path.isdir("./environment_mix/0004000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    api_keys = _load("api_keys.json")
    request_events = _load("request_events.json")

    def _log_event(http_status, api_key_id=None, response_payload=None, error_code=None, error_message=None):
        latency_ms = max(0, int((time.time() - t0) * 1000))
        ev = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "getTime",  # constrained enum; admin tools not included
            "request_payload": {"tool": "updateApiKey", "id": id, "name": name, "rate_limit_rpm": rate_limit_rpm, "daily_limit": daily_limit},
            "timestamp_input": None,
            "response_payload": response_payload,
            "http_status": int(http_status),
            "error_code": error_code,
            "error_message": (error_message[:300] if isinstance(error_message, str) else error_message),
            "latency_ms": latency_ms,
            "client_ip": None,
            "user_agent": None,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        request_events.append(ev)
        _save("request_events.json", request_events)

    # Validate input
    if not isinstance(id, str) or not id.strip():
        _log_event(400, None, None, "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if name is not None:
        if not isinstance(name, str):
            _log_event(400, None, None, "VALIDATION_ERROR", "name must be a string")
            return _err("VALIDATION_ERROR", "name must be a string")
        if not (1 <= len(name) <= 200):
            _log_event(400, None, None, "VALIDATION_ERROR", "name length must be between 1 and 200")
            return _err("VALIDATION_ERROR", "name length must be between 1 and 200")

    if rate_limit_rpm is not None:
        if not isinstance(rate_limit_rpm, int):
            _log_event(400, None, None, "VALIDATION_ERROR", "rate_limit_rpm must be an integer")
            return _err("VALIDATION_ERROR", "rate_limit_rpm must be an integer")
        if not (1 <= rate_limit_rpm <= 60000):
            _log_event(400, None, None, "VALIDATION_ERROR", "rate_limit_rpm must be between 1 and 60000")
            return _err("VALIDATION_ERROR", "rate_limit_rpm must be between 1 and 60000")

    if daily_limit is not None:
        if not isinstance(daily_limit, int):
            _log_event(400, None, None, "VALIDATION_ERROR", "daily_limit must be an integer")
            return _err("VALIDATION_ERROR", "daily_limit must be an integer")
        if not (1 <= daily_limit <= 10000000):
            _log_event(400, None, None, "VALIDATION_ERROR", "daily_limit must be between 1 and 10000000")
            return _err("VALIDATION_ERROR", "daily_limit must be between 1 and 10000000")

    if name is None and rate_limit_rpm is None and daily_limit is None:
        _log_event(400, None, None, "VALIDATION_ERROR", "At least one mutable field must be provided")
        return _err("VALIDATION_ERROR", "At least one mutable field must be provided")

    # Ambient authentication: need at least one active key to exist
    any_active = any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys)
    if not any_active:
        _log_event(401, None, None, "UNAUTHORIZED", "No active credentials available")
        return _err("UNAUTHORIZED", "Not authorized")

    # Find key
    idx = next((i for i, k in enumerate(api_keys) if isinstance(k, dict) and k.get("id") == id), None)
    if idx is None:
        _log_event(404, None, None, "NOT_FOUND", "API key not found")
        return _err("NOT_FOUND", "API key not found")

    key = api_keys[idx]

    # Cannot update/reactivate revoked key
    if key.get("status") == "revoked":
        _log_event(409, key.get("id"), None, "INVALID_TRANSITION", "Cannot update a revoked key")
        return _err("INVALID_TRANSITION", "Cannot update a revoked key")

    # Apply updates
    changed = False
    if name is not None and name != key.get("name"):
        key["name"] = name
        changed = True
    if rate_limit_rpm is not None and rate_limit_rpm != key.get("rate_limit_rpm"):
        key["rate_limit_rpm"] = rate_limit_rpm
        changed = True
    if daily_limit is not None and daily_limit != key.get("daily_limit"):
        key["daily_limit"] = daily_limit
        changed = True

    if not changed:
        # Idempotent: if caller sends same values, it is still a successful update with refreshed updated_at.
        pass

    # Enforce constraints for status/ revocation timestamps
    if key.get("status") == "active":
        key["revoked_at"] = None

    key["updated_at"] = now_iso
    api_keys[idx] = key
    _save("api_keys.json", api_keys)

    out = {
        "id": key.get("id"),
        "key_prefix": key.get("key_prefix"),
        "name": key.get("name"),
        "status": key.get("status"),
        "rate_limit_rpm": key.get("rate_limit_rpm"),
        "daily_limit": key.get("daily_limit"),
        "last_used_at": key.get("last_used_at"),
        "revoked_at": key.get("revoked_at"),
        "created_at": key.get("created_at"),
        "updated_at": key.get("updated_at"),
    }

    _log_event(200, key.get("id"), {"api_key": out}, None, None)
    return {"api_key": out}
